import { expectStatus, test } from "../../fixtures";

test("An audit trail from another tenant is invisible", { tag: "@AUD-02" }, async ({ apiAs, factory }) => {
  // Arrange
  const member = await apiAs("member");
  const owner = await apiAs("otherTenant");
  const vendor = await factory.vendor({ as: "otherTenant" });
  // The owning tenant can read it, so a 404 below means it is hidden, not missing.
  await expectStatus(await owner.get(`/api/vendors/${vendor.id}/audit`), 200);

  // Act
  const response = await member.get(`/api/vendors/${vendor.id}/audit`);

  // Assert
  await expectStatus(response, 404);
});
